const f = $input.first().json;
const errors = [];
for (const k of ['proveedor_id','numero','fecha_emision','moneda','subtotal','impuesto','total']) if (f[k] === undefined || f[k] === null || f[k] === '') errors.push(`${k} es obligatorio`);
const subtotal=Number(f.subtotal), impuesto=Number(f.impuesto), total=Number(f.total);
if (!Number.isFinite(subtotal)||subtotal<0) errors.push('subtotal inválido');
if (!Number.isFinite(impuesto)||impuesto<0) errors.push('impuesto inválido');
if (!Number.isFinite(total)||total<0||Math.abs(total-(subtotal+impuesto))>0.01) errors.push('total debe ser subtotal + impuesto');
if (!['CRC','USD'].includes(f.moneda)) errors.push('moneda inválida');
return [{json:{ok:errors.length===0,data:errors.length?null:{...f,subtotal,impuesto,total},error:errors.length?errors.join('; '):null}}];
